description:
Write an interface and several implementations that clean up text, plus a pipeline that combines them. The project has three files:

```java
// TextFilter.java
interface TextFilter {
    String apply(String text);
    default String name() { return getClass().getSimpleName(); }
}

// Filters.java: the simple filters, as static nested classes
class Filters {
    static class Trim implements TextFilter          // removes spaces at both ends and collapses runs of spaces to one
    static class LowerCase implements TextFilter
    static class ReplaceWords implements TextFilter  // ReplaceWords(Map<String, String> replacements): whole words, case-sensitive
    static class MaxLength implements TextFilter     // MaxLength(int max): cuts to max characters, ending with "..." when cut
}

// Pipeline.java
class Pipeline implements TextFilter, Iterable<TextFilter>
    Pipeline add(TextFilter filter)                  // returns this, so calls can be chained
    String apply(String text)                        // applies every filter in order
    String name()                                    // "Pipeline[Trim, LowerCase]"
```

- `new Filters.ReplaceWords(Map.of("teh", "the"))` turns `"teh cat ate teh fish"` into `"the cat ate the fish"`, but leaves `"tehran"` alone. Words are separated by single spaces.
- `MaxLength` throws `IllegalArgumentException` for a `max` below 3.
- A `Pipeline` is itself a `TextFilter`, so pipelines can contain pipelines.

starter.TextFilter.java:
interface TextFilter {
    String apply(String text);
    default String name() { return getClass().getSimpleName(); }
}

solution.TextFilter.java:
interface TextFilter {
    String apply(String text);
    default String name() { return getClass().getSimpleName(); }
}

solution.Filters.java:
import java.util.Map;

class Filters {
    static class Trim implements TextFilter {
        public String apply(String text) { return text.trim().replaceAll(" +", " "); }
    }

    static class LowerCase implements TextFilter {
        public String apply(String text) { return text.toLowerCase(); }
    }

    static class ReplaceWords implements TextFilter {
        private final Map<String, String> replacements;

        ReplaceWords(Map<String, String> replacements) { this.replacements = Map.copyOf(replacements); }

        public String apply(String text) {
            String[] words = text.split(" ", -1);
            for (int i = 0; i < words.length; i++) words[i] = replacements.getOrDefault(words[i], words[i]);
            return String.join(" ", words);
        }
    }

    static class MaxLength implements TextFilter {
        private final int max;

        MaxLength(int max) {
            if (max < 3) throw new IllegalArgumentException("max must be at least 3");
            this.max = max;
        }

        public String apply(String text) {
            return text.length() <= max ? text : text.substring(0, max - 3) + "...";
        }
    }
}

solution.Pipeline.java:
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

class Pipeline implements TextFilter, Iterable<TextFilter> {
    private final List<TextFilter> filters = new ArrayList<>();

    Pipeline add(TextFilter filter) {
        filters.add(filter);
        return this;
    }

    public String apply(String text) {
        String result = text;
        for (TextFilter f : filters) result = f.apply(result);
        return result;
    }

    @Override
    public String name() {
        List<String> names = new ArrayList<>();
        for (TextFilter f : filters) names.add(f.name());
        return "Pipeline[" + String.join(", ", names) + "]";
    }

    public Iterator<TextFilter> iterator() { return filters.iterator(); }
}

unitTests:
test("single filters", () -> {
    checkEq(new Filters.Trim().apply("   too    many   spaces  "), "too many spaces");
    checkEq(new Filters.LowerCase().apply("MiXeD"), "mixed");
    checkEq(new Filters.ReplaceWords(Map.of("teh", "the", "adn", "and")).apply("teh cat adn teh tehran fish"), "the cat and the tehran fish");
    checkEq(new Filters.MaxLength(10).apply("short"), "short");
    checkEq(new Filters.MaxLength(10).apply("a much longer text"), "a much ...");
    checkThrows(IllegalArgumentException.class, () -> new Filters.MaxLength(2));
    checkEq(new Filters.Trim().name(), "Trim");
});

test("a pipeline", () -> {
    Pipeline p = new Pipeline().add(new Filters.Trim()).add(new Filters.LowerCase()).add(new Filters.ReplaceWords(Map.of("teh", "the")));
    checkEq(p.apply("  TEH   Quick  Fox "), "the quick fox");
    checkEq(p.name(), "Pipeline[Trim, LowerCase, ReplaceWords]");
    TextFilter asFilter = p;
    checkEq(asFilter.apply("TEH"), "the");
});

test("nesting and iterating", () -> {
    Pipeline inner = new Pipeline().add(new Filters.Trim()).add(new Filters.LowerCase());
    Pipeline outer = new Pipeline().add(inner).add(new Filters.MaxLength(8));
    checkEq(outer.apply("   HELLO   THERE WORLD"), "hello...");
    checkEq(outer.name(), "Pipeline[Pipeline[Trim, LowerCase], MaxLength]");
    int count = 0;
    for (TextFilter f : outer) count++;
    checkEq(count, 2);
    checkEq(new Pipeline().apply("unchanged"), "unchanged");
});

